953,0.361498],[42.433074,0.361507],[42.433152,0.361486],[42.43322,0.361443],[42.433294,0.361342],[42.433347,0.361219],[42.433395,0.36113],[42.433469,0.361046],[42.43355,0.360946],[42.4336,0.360849],[42.433657,0.360697],[42.433753,0.360522],[42.433818,0.360494],[42.433975,0.360466],[42.434036,0.360423],[42.434094,0.360383],[42.434155,0.360382],[42.434228,0.36044],[42.434272,0.360535],[42.434286,0.360616],[42.434277,0.360704],[42.434249,0.360817],[42.434234,0.360941],[42.434263,0.361093],[42.434301,0.361227],[42.43431,0.361318],[42.434287,0.361391],[42.434273,0.36149],[42.434301,0.36162],[42.434363,0.361797],[42.434459,0.362089],[42.434522,0.362293],[42.43454,0.362377],[42.434548,0.362468],[42.434543,0.362561],[42.434528,0.362696],[42.434503,0.362863],[42.434509,0.362942],[42.434545,0.363027],[42.434648,0.363105],[42.434733,0.363134],[42.434817,0.363148],[42.434896,0.363183],[42.43496,0.363296],[42.434976,0.36344],[42.434926,0.363556],[42.434823,0.363625],[42.434742,0.363675],[42.434677,0.363748],[42.434618,0.363836],[42.434572,0.363934],[42.434529,0.364042],[42.434482,0.364128],[42.434427,0.364202],[42.434353,0.364295],[42.434313,0.364381],[42.434271,0.364532],[42.434222,0.364756],[42.434198,0.364847],[42.43414,0.365022],[42.434054,0.36527],[42.434019,0.365394],[42.434005,0.36549],[42.434005,0.36561],[42.433995,0.36571],[42.43399,0.365985],[42.433978,0.366119],[42.433962,0.366221],[42.433939,0.366299],[42.433893,0.366385],[42.433764,0.366571]]$coords$::jsonb;
  v_landmarks jsonb := $landmarks$[[42.410145,0.38941],[42.433764,0.366571],[42.427374,0.366043],[42.410956,0.394731],[42.434005,0.36561],[42.434011,0.365656],[42.410902,0.346974],[42.410947,0.394522]]$landmarks$::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
  v_closing_gap_m double precision;
  v_landmark_gap_m double precision;
begin
  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);
  select h.id,h.latitude,h.longitude,h.published,h.trace_available,
      h.official_url,h.description,h.distance_km,h.route_type,
      h.duration_minutes,h.ascent_m,
      t.status,t.segments,t.geometry_source,t.geometry_source_url,
      t.official,t.continuity_checked,t.checked_at
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-9691543'
      and h.source='openstreetmap' and h.source_type='relation'
      and h.external_id=9691543
      and h.name='Campo - Foradada del Toscar - Senz'
      and h.route_ref='PR-HU 121' and h.raw_tags->>'ref'='PR-HU 121'
      and h.source_url='https://www.openstreetmap.org/relation/9691543'
      and (h.official_url is not distinct from null
        or h.official_url='https://turismoribagorza.org/ruta/pr-hu-121-campo-foradada-del-toscar-senz/')
      and h.region_code='huesca' and h.province='Huesca'
      and h.latitude=42.4174248 and h.longitude=0.3708913
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='huesca' and r.published)
    for update of h,t;
  if not found then
    raise exception 'PR-HU 121 route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/46_pr_hu_121.gpx'
      and v_route.geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 121'
      and v_route.segments=jsonb_build_array(v_points)
      and v_route.official and v_route.continuity_checked
      and v_route.checked_at is not null
      and v_route.published and v_route.trace_available
      and v_route.official_url='https://turismoribagorza.org/ruta/pr-hu-121-campo-foradada-del-toscar-senz/'
      and v_route.distance_km=15.84
      and v_route.route_type='Lineal'
      and v_route.duration_minutes=370
      and v_route.ascent_m=1055
      and v_route.description='PR-HU 121 de Campo a Senz por la ermita de San Blascut, Collabardina y Peñamortés, con visita a Foradada del Toscar y regreso al cruce. La ficha oficial advierte de tramos afectados por desprendimientos en el ramal hacia Senz.' then
      return;
    end if;
    raise exception 'PR-HU 121 route has another ready trace or publication state';
  end if;
  if v_route.status is distinct from 'missing'
    or v_route.published is distinct from false
    or v_route.trace_available is distinct from false
    or v_route.segments is not null or v_route.geometry_source_url is not null
    or v_route.geometry_source is distinct from 'OpenStreetMap'
    or v_route.official is distinct from false
    or v_route.continuity_checked is distinct from true
    or v_route.official_url is distinct from null
    or v_route.description is distinct from 'Campo - Foradada del Toscar - Senz'
    or v_route.distance_km is distinct from 15.000
    or v_route.ascent_m is not null or v_route.duration_minutes is not null
    or v_route.route_type is not null then
    raise exception 'PR-HU 121 hidden route state changed';
  end if;
  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 42.39 and 42.44 and lon between 0.34 and 0.4) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;
  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(0.394731,42.410956)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(0.366571,42.433764)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision))
    into v_start_gap_m,v_end_gap_m,v_closing_gap_m;
  select max(nearest.gap_m) into v_landmark_gap_m
    from jsonb_array_elements(v_landmarks) as w(landmark)
    cross join lateral (
      select min(ST_DistanceSphere(
        ST_MakePoint((point->>1)::double precision,(point->>0)::double precision),
        ST_MakePoint((w.landmark->>1)::double precision,(w.landmark->>0)::double precision))) gap_m
      from jsonb_array_elements(v_coords) as p(point)
    ) nearest;
  if v_count<>1223 or v_invalid>0
    or abs(v_length_km-15.844595)>0.015
    or v_max_gap_km>0.06 or v_center_gap_km>0.12
    or v_start_gap_m>2 or v_end_gap_m>2 or v_closing_gap_m<1000
    or v_landmark_gap_m>10 then
    raise exception 'PR-HU 121 GPS validation failed: points %, length %, gap %, center %, start %, end %, closure %, landmarks %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_closing_gap_m,v_landmark_gap_m,v_invalid;
  end if;
  update public.hiking_route_tracks
    set status='ready',segments=jsonb_build_array(v_points),checked_at=now(),
      continuity_checked=true,geometry_source='Comarca de Ribagorza - GPX oficial PR-HU 121',
      geometry_source_url='https://turismoribagorza.org/wp-content/uploads/2025/06/46_pr_hu_121.gpx',official=true
    where route_id=v_route.id and status='missing';
  if not found then
    raise exception 'PR-HU 121 track state changed';
  end if;
  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),route_type='Lineal',
      duration_minutes=370,ascent_m=1055,
      official_url='https://turismoribagorza.org/ruta/pr-hu-121-campo-foradada-del-toscar-senz/',description='PR-HU 121 de Campo a Senz por la ermita de San Blascut, Collabardina y Peñamortés, con visita a Foradada del Toscar y regreso al cruce. La ficha oficial advierte de tramos afectados por desprendimientos en el ramal hacia Senz.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'PR-HU 121 publication state changed';
  end if;
end
$curate$;
